    float a = float(i) * 0.785398 + (i < 8 ? 0.0 : 0.392699), r = i < 8 ? 0.1 : 0.18;
    vec2 u = clamp(uv + vec2(cos(a) * res.y / res.x, sin(a)) * r, 0.0, 1.0);
    if (viewZ(u) < gZin + 5e-4) { c += texture2D(tScene, u).rgb; n += 1.0; }
