  float ok = 1.0, Lg = 0.0, Ll = 0.0, region = 0.0, fl = 0.0;
  vec2 h = enterP(p, d, uOut, uOutY, n);
  if (!(h.x > 0.0 && h.x < h.y)) ok = 0.0;                              // 没碰到瓶子：普通光照，不归焦散管
