  for (int k = 0; k < 2; k++) {
    float t = exitP(p, d, uOut, uOutY, no);
    Lg += t; p += d * t;
    vec3 o = refract(d, -no, uEg);
    if (dot(o, o) > 0.5) { d = o; left = true; break; }
    bounce = fid(no) + 1.0; d = reflect(d, no);
  }
  if (!left || d.y > -1e-3) ok = 0.0;
