  vOk = ok; vSrc = position.xy * uExt; vDst = land.xz; vIn = -d;
  vPath = vec4(fin, region, fl, fid(no) + 10.0 * bounce);                              // 走的面不同就是不同的路：跨路的三角形丢掉
  vT = exp(-(uGa * Lg + uLa * Ll));                                     // 本通道的比尔–朗伯吸收
