  if (length(a + ab * clamp(-dot(a, ab) / max(dot(ab, ab), 1e-12), 0.0, 1.0)) < 0.019000) ok = 0.0;
  d = refract(d, n, 1.0 / uEg);
  vec3 nc; vec2 hc = enterP(p, d, uCav, uCavY, nc);
  if (hc.x > 0.0 && hc.x < hc.y) {                                      // 进内腔
    Lg += hc.x; p += d * hc.x;
    bool liquid = p.y < 0.074000;
    if (!liquid) {                                                      // 液面以上是空气：落到液面，或者撞上对面的壁
      d = refract(d, nc, uEg); region = 1.0;
      vec3 nx; float t = exitP(p, d, uCav, uCavY, nx), tf = d.y < 0.0 ? (0.074000 - p.y) / d.y : 1e3;
