  if (dot(d, d) < 0.5) ok = 0.0;                                        // 里面某个界面全反射
  // 出瓶：全反射就在玻璃里反射一次再出（从竖直面进来的光到不了底面以外的直角面，靠这一下才从底面出去）
  vec3 no; float bounce = 0.0; bool left = false;
